INSERT INTO FIN_EXERCISE_PLAN SELECT * FROM (
values #{cashId,jdbcType=VARCHAR}, CASE #{item.xqmode,jdbcType=VARCHAR} WHEN '赎回' THEN '01' WHEN '回售' THEN '02' ELSE '' END, #{item.applydatestr,jdbcType=DATE}, #{item.applydateend,jdbcType=DATE}, #{item.exerciseDate,jdbcType=DATE}, null, #{item.xqnetprice,jdbcType=DECIMAL}, #{item.xqclause,jdbcType=VARCHAR}, #{finprodId,jdbcType=VARCHAR}, 'F01', 0, #{item.createUser,jdbcType=VARCHAR}, #{item.createDept,jdbcType=VARCHAR}, #{item.createTime,jdbcType=DATE}, #{item.updateUser,jdbcType=VARCHAR}, #{item.updateTime,jdbcType=DATE} FROM DUAL
)

INSERT INTO FIN_CASH_PLAN SELECT * FROM (
values #{cashId,jdbcType=VARCHAR} CASH_ID, #{index} + 1 CASH_NUM, #{item.theorydatestr,jdbcType=DATE} VDATE_UNADJUST, #{item.theorydateend,jdbcType=DATE} MDATE_UNADJUST, null PAY_DATE_UNADJUST, #{item.actdatestr,jdbcType=DATE} VDATE, #{item.actdateend,jdbcType=DATE} MDATE, #{item.plandate,jdbcType=DATE} PAY_DATE, (#{item.actdateend,jdbcType=DATE} - #{item.actdatestr,jdbcType=DATE}) TERMDAYS, null VDATE_Y, #{item.actdatestr,jdbcType=DATE} VDATE_TERM, #{item.actdateend,jdbcType=DATE} MDATE_TERM, null TERMDAYS_TERM, null PRIN_AMT, null INT_PRIN_AMT, #{item.planintamt,jdbcType=DECIMAL} INT_AMT, null IS_PAY_INT, #{item.planintamt,jdbcType=DECIMAL} CASH_AMT, '01', null CALC_FUNCTION, null FREQUENCY, #{finprodId,jdbcType=VARCHAR} FINPROD_ID, 'F01' FINPROD_TYPE, 0 BRANCH, '02' PAY_TYPE, #{item.createUser,jdbcType=VARCHAR}, #{item.createDept,jdbcType=VARCHAR}, #{item.createTime,jdbcType=DATE}, #{item.updateUser,jdbcType=VARCHAR}, #{item.updateTime,jdbcType=DATE} FROM DUAL
)

INSERT INTO FIN_CASH_PLAN SELECT * FROM (
values #{cashId,jdbcType=VARCHAR} CASH_ID, #{index} + 1 CASH_NUM, #{item.jsdatestr,jdbcType=DATE} VDATE_UNADJUST, #{item.jsdateend,jdbcType=DATE} MDATE_UNADJUST, null PAY_DATE_UNADJUST, #{item.jsdatestr,jdbcType=DATE} VDATE, #{item.jsdateend,jdbcType=DATE} MDATE, #{item.paydate,jdbcType=DATE} PAY_DATE, (#{item.jsdateend,jdbcType=DATE} - #{item.jsdatestr,jdbcType=DATE}) TERMDAYS, null VDATE_Y, #{item.jsdatestr,jdbcType=DATE} VDATE_TERM, #{item.jsdateend,jdbcType=DATE} MDATE_TERM, null TERMDAYS_TERM, #{item.remoney,jdbcType=DECIMAL} PRIN_AMT, #{item.jxamt,jdbcType=DECIMAL} INT_PRIN_AMT, null INT_AMT, null IS_PAY_INT, #{item.remoney,jdbcType=DECIMAL} CASH_AMT, '01', null CALC_FUNCTION, null FREQUENCY, #{finprodId,jdbcType=VARCHAR} FINPROD_ID, 'F01' FINPROD_TYPE, 0 BRANCH, '02' PAY_TYPE, #{item.createUser,jdbcType=VARCHAR}, #{item.createDept,jdbcType=VARCHAR}, #{item.createTime,jdbcType=DATE}, #{item.updateUser,jdbcType=VARCHAR}, #{item.updateTime,jdbcType=DATE} FROM DUAL
